import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomTextArea,
} from "../../../components";
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "dayjs/locale/en-gb";
import { useDispatch } from "react-redux";
import { getLoggedInUser } from "../../../helpers/authUtils";

import useApi from "../../../hooks/useApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import { Modal } from "antd";
import clustersApi from "../../../api/clustersApi";
import rolesApi from "../../../api/rolesApi";

export default function RoleFormModal({
  openEditModal,
  setopenEditModal,
  selectedRole,
  updated,setUpdated
}) {
  const dispatch = useDispatch();
  const [user, setUser] = useState();
  const [errors, setErrors] = useState();
  const { currentColor, loggedInUser } = useStateContext();


  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const rolesActionApi = useApi(rolesApi.rolesAction);
  const handleRolesAction = async (data) => {
    await rolesActionApi.request(data);
  };


  useEffect(()=>{
    if(rolesActionApi.data){
      if(rolesActionApi.data.role){
        toast.success(rolesActionApi.data.response_message)
        setopenEditModal(false)
        setUpdated(true)
      }

      if(rolesActionApi.data.errors){
        setErrors(rolesActionApi.data.errors)
      }
    }
    console.log("rolesActionApi.data",rolesActionApi.data)
  },[rolesActionApi.data])

  const formik = useFormik({
    initialValues: {
      cluster: selectedRole ? {"label":selectedRole.cluster_title,"value":selectedRole.cluster} : "",
      title: selectedRole ? selectedRole.title : "",
      description: selectedRole ? selectedRole.description : "",
    },

    validationSchema: Yup.object({
      title: Yup.string().required("Title is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action
      let data = null;
      console.log("VALZ",values)

      if (selectedRole) {
        data = {
          action: "UpdateRole",
          role_details: {
            "id":selectedRole.id,
            title: values.title,
            cluster: values.cluster.value,
            description: values.description,
          },
        };
      } else {
        data = {
          action: "CreateRole",
          role_details: {
            title: values.title,
            cluster: values.cluster.value,
            description: values.description,
          },
        };
      }

      handleRolesAction(data);

      resetForm();
    },
  });

  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setopenEditModal(false);
  };
  const handleCancel = () => {
    setopenEditModal(false);
  };

  //Retrieve clusters
  const [clusters, setClusters] = useState([]);

  const getClustersApi = useApi(clustersApi.clustersAction);

  const getClusters = () => {
    getClustersApi.request({
      action: "GetClusters",
    });
  };

  useEffect(() => {
    getClusters();
  }, []);

  useEffect(() => {
    if (getClustersApi.data) {
      if (getClustersApi.data && getClustersApi.data.length) {
        setClusters(
          getClustersApi.data.map((i) => ({ label: i.title, value: i.id }))
        );
      }
    }
  }, [getClustersApi.data]);

  return (
    <div className=" max-w-fit min-w-fit">
      <ToastContainer theme="colored" position="bottom-center" />
      <Modal
        width={600}
        className="w-full text-center capitalize"
        title={selectedRole ? "EDIT " + selectedRole.title : "ADD NEW ROLE"}
        open={openEditModal}
        onOk={handleOk}
        onCancel={handleCancel}
        closeIcon={true}
        closable={false}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
            className="w-full"
          >
            <CustomInput
              id="title"
              name="title"
              required={true}
              onChange={formik.handleChange}
              placeholder="Enter title"
              label="Enter title"
              size="large"
              type="text"
              value={formik.values.title}
            />
          </CustomFormItem>

          <CustomFormItem
            className="w-full"
            touched={formik.touched.cluster}
            error={formik.errors.cluster}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="cluster"
              id="cluster"
              label="Select user cluster"
              size="large"
              onChange={(value) => formik.setFieldValue("cluster", value)}
              value={formik.values.cluster}
              placeholder="Select user cluster"
              options={clusters}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.description}
            error={formik.errors.description}
            className="w-full"
          >
            <CustomTextArea
              rows={2}
              id="description"
              name="description"
              onChange={formik.handleChange}
              placeholder="Any description"
              label="Any description"
              size="large"
              type="text"
              value={formik.values.description}
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button
              style={{ background: currentColor }}
              className="w-36 rounded-md"
              color="primary"
              type="submit"
            >
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
