import React, { useEffect, useState } from 'react'
import RolesTable from './RolesTable'

import useApi from '../../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import rolesApi from '../../../api/rolesApi';
import { Loading } from '../../../components';
import RoleFormModal from './RoleFormModal';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Cluster", uid: "cluster_title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function RolesList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [role, setRole] = useState()
    const [frequencies, setFrequencies] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const rolesActionsApi = useApi(rolesApi.rolesAction)

    const getEntityRoles = async () => {
        await rolesActionsApi.request({
            "action": "GetEntityRoles"

        })
    }


    useEffect(() => {
        getEntityRoles()
    }, [])


    const handleEditAction = (item) => {

        setopenEditModal(true)
        setRole(item)
        setmodalTitle(`Edit ${item.title}`)
        setUpdated(false)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new body system")
        setRole(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/systems/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/systems/delete/${item.id}`)
    }


    useEffect(() => {

        if (rolesActionsApi.data && rolesActionsApi.data.length) {

            setFrequencies(rolesActionsApi.data)
        }
    }, [rolesActionsApi.data])

    useEffect(() => {
        if(updated)
        getEntityRoles()
    }, [updated])


    //Filtering data
    useEffect(() => {
        setdata(frequencies)
    }, [frequencies])


    const handleFilter = (e) => {
        const search_param = e
        if (frequencies && frequencies.length > 0 && search_param && search_param !== '') {
            setdata(frequencies.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(frequencies);
        }

    };

    return rolesActionsApi.loading ? <Loading loading={rolesApi.loading} /> : (
        <div>
            {openEditModal && <RoleFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} selectedRole={role} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <RolesTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default RolesList